# Amazon Textract implementation
import boto3
from boto3.textract.model import DocumentBlocks

def extract_key_value_pairs(document_bytes):
    textract = boto3.client('textract')
    response = textract.analyze_document(
        Document={'Bytes': document_bytes},
        FeatureTypes=['FORMS']
    )

    key_values = {}
    for block in response['Blocks']:
        if block['BlockType'] == 'KEY_VALUE_SET':
            key = None
            value = None
            for relation in block.get('Relations', []):
                if relation['Type'] == 'KEY':
                    for id in relation['Ids']:
                        if response['Blocks'][id]['BlockType'] == 'KEY':
                            key = response['Blocks'][id]['Text']
                elif relation['Type'] == 'VALUE':
                    for id in relation['Ids']:
                        if response['Blocks'][id]['BlockType'] == 'VALUE':
                            value = response['Blocks'][id]['Text']
            if key and value:
                key_values[key] = value
    return key_values
